from lib import *
S = SS('v17')
steps = [
    step("nginx 转发给后端的请求。client 发 GET /hello?a=1,头里有 Host: shop.example.test、X-Trace、Accept-Encoding: gzip、空值的 X-Empty、带下划线的 X_under。默认配置(只有 proxy_pass):后端看到的请求行是 GET /hello?a=1 HTTP/1.1(nginx 1.31.6 默认就用 HTTP/1.1 到上游,我没有测旧版本);Host 变成了 u(upstream 组的名字,不是 client 的 shop.example.test);X-Trace、Accept-Encoding、X-Empty 原样;X_under 没有了(带下划线的请求头默认被丢弃);没有 X-Forwarded-For、X-Real-IP。常见写法(proxy_set_header Host $host 等):Host 是 shop.example.test,多了 X-Forwarded-For 和 X-Real-IP,都是 127.0.0.1;X_under 仍然没有。", t=tl(S(1)), mark=lidx(S(1), 'Host  ', 'X_under'), done=lidx(S(1), 'X-Forwarded-For', 'X-Real-IP', 'X-Trace'), b=bars([['默认:Host 变成', 1, 'u'], ['默认:X_under 到达后端', 0, '0(被丢弃)'], ['默认:X-Forwarded-For', 0, '(没有)'], ['常见写法:X-Forwarded-For', 1, '127.0.0.1']], 1, mark=[0, 1], cur=[2], done=[3]), kv=KV([['Host(默认)', 'u,不是 client 的 shop.example.test'], ['X_under', '默认被丢弃'], ['X-Forwarded-For', '默认没有,要自己加']], ['Host(默认)'])),
    step("nginx 回给 client 的响应。后端的响应头有 Server: BaseHTTP/0.6 Python/3.14.8、X-Backend: b1、Keep-Alive: timeout=5、X-Secret-Internal: yes、Date。经过 nginx(默认):Server 变成 nginx/1.31.6;Keep-Alive 没有了(逐跳头不转发);多了 Connection: keep-alive;X-Backend 和 X-Secret-Internal 原样转发(内部头泄露给了 client)。加 proxy_hide_header X-Secret-Internal 和 proxy_pass_header Server:X-Secret-Internal 没有了,Server 又变回后端的 BaseHTTP/0.6 Python/3.14.8。content-length 的差别(106 对 93)是因为回显的响应体里列出的请求头不同,不是 nginx 改的。", t=tl(S(2)), mark=lidx(S(2), 'server', 'x-secret-internal'), done=lidx(S(2), 'keep-alive', 'connection'), b=bars([['默认:Server 被换成 nginx', 1, 'nginx/1.31.6'], ['默认:Keep-Alive 头', 0, '(没有)'], ['默认:X-Secret-Internal', 1, 'yes(泄露)'], ['hide 后:X-Secret-Internal', 0, '(没有)']], 1, mark=[0, 2], cur=[1], done=[3]), kv=KV([['Server', '默认被换成 nginx/1.31.6'], ['Keep-Alive', '逐跳头,不转发'], ['内部头', '默认原样转发,要 proxy_hide_header']], ['内部头'])),
    step("listener、路由、上游三层。一个 nginx 里两个 listener(端口 P1、P2),P1 上有两个 server 块(按 Host 选),server 里按路径匹配三条路由,两个上游池。P1 + Host shop.test:/api/users 落到 b1,/static/a.js 落到 b2,/other 由 nginx 自己回 shop-default。P1 + Host unknown.test:对不上任何 server_name,落到该端口的 default_server,回 404 no-such-host。P2 上只有一个 server 块(admin.test):/api/users 落到 b2;Host 写成 shop.test 也落到同一个 server 块,b2。第一层 listener(端口加 server_name)选 server 块,第二层路由(location)选规则,第三层上游选后端。", t=tl(S(3)), mark=lidx(S(3), 'unknown.test'), done=lidx(S(3), 'shop.test    | /api/users', 'shop.test    | /static', 'admin.test'), b=bars([['P1 shop.test /api/', 1, 'b1'], ['P1 shop.test /static/', 2, 'b2'], ['P1 unknown.test', 404, '404 default_server'], ['P2 任意 Host', 2, 'b2']], 404, done=[0, 1, 3], mark=[2]), kv=KV([['listener → server 块', '端口 + Host(server_name)'], ['路由', 'location 按路径选规则'], ['上游', 'upstream 里选后端'], ['Host 对不上', '落到 default_server']], ['Host 对不上'])),
]
